/** CLDR 47 plural rules per locale (ADR 0003): the category of a number. */
const PLURALS: Readonly<Record<string, (n: number) => string>> = {
  "en": (n) => {
    const s = String(Math.abs(n))
    const dot = s.indexOf(".")
    const f = dot < 0 ? "" : s.slice(dot + 1)
    const t = f.replace(/0+$/, "")
    const o = { n: Math.abs(n), i: Math.trunc(Math.abs(n)), v: f.length, w: t.length, f: Number(f || 0), t: Number(t || 0), c: 0, e: 0 }
    if ((o.i === 1 && o.v === 0)) return "one"
    return "other"
  },
  "de": (n) => {
    const s = String(Math.abs(n))
    const dot = s.indexOf(".")
    const f = dot < 0 ? "" : s.slice(dot + 1)
    const t = f.replace(/0+$/, "")
    const o = { n: Math.abs(n), i: Math.trunc(Math.abs(n)), v: f.length, w: t.length, f: Number(f || 0), t: Number(t || 0), c: 0, e: 0 }
    if ((o.i === 1 && o.v === 0)) return "one"
    return "other"
  },
}

/**
 * Builds the emails with the values that vary by environment (RUN-04). Call it once, for
 * example at startup, and reuse the result. Data passed to render() can't override them.
 */
export function createEmails(context: EmailContext): Emails {
  const values = readContext(["siteUrl"], context)
  return {
    orderConfirmation: createTemplate(
      "order-confirmation",
      "transactional",
      {"type":"object","properties":{"customerName":{"type":"string","constraints":{"minLength":1}},"orderNumber":{"type":"string","constraints":{"minLength":1}},"orderUrl":{"type":"string","url":true},"items":{"type":"array","items":{"type":"object","properties":{"name":{"type":"string"},"qty":{"type":"number"}},"required":["name","qty"]}},"discount":{"type":"string"}},"required":["customerName","orderNumber","orderUrl","items"]},
      locales,
      TEMPLATES.orderConfirmation,
      values,
      true,
      PLURALS,
    ) as EmailTemplate<"order-confirmation", OrderConfirmationData>,
  }
}
